     % Draw the grid
     \foreach \row in {1,...,\boardrows} {
       \foreach \column in {1,...,\boardcolumns} {
         \node[minimum size=0.9cm, inner sep=0] (square-\row-\column) at (\column * 1 cm, \row * 1 cm) {\square{0.9}};
       }
     }
   \end{tikzpicture}
   ```
